'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Rounds a single-precision floating-point number to the nearest multiple of `10^n`.
*
* @private
* @param {number} x - input value
* @param {integer} n - integer power of `10`
* @returns {number} rounded value
*
* @example
* var v = roundnf( 3.141592, -2 );
* // returns 3.14
*
* @example
* var v = roundnf( 3.141592, 0 );
* // returns 3.0
*
* @example
* var v = roundnf( 1234.56, 2 );
* // returns 1200.0
*/
function roundnf( x, n ) {
	return addon( x, n );
}


// EXPORTS //

module.exports = roundnf;
